    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> t = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) t.add(st.nextToken());
        }
        int n = Integer.parseInt(t.get(0));
        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = t.get(1 + i);
        int q = Integer.parseInt(t.get(1 + n));
        String[] queries = new String[q];
        for (int i = 0; i < q; i++) queries[i] = t.get(2 + n + i);
        boolean[] res = searchWords(words, queries);
        StringBuilder sb = new StringBuilder();
        for (boolean r : res) sb.append(r ? "YES" : "NO").append("\n");
        System.out.print(sb);
    }
}
